import {binarySTL,volume,zip} from './geometry.js';
export function scadSource(m,kernel){const p=m.p;return `// PETAL / Parametric Dish Studio\n// Editable source. Dimensions in mm. No external libraries.\n/* [Dish] */\ndiameter = ${p.diameter}; // [180:1:1200]\nfd = ${p.fd}; // [0.25:0.01:0.80]\nthickness = ${p.thickness}; // [1.6:0.1:6]\n/* [Rear construction] */\nrear_style = ${p.rearStyle}; // [0:Curved shell,1:Two-facet rear]\nfacet_angle = ${p.facetAngle}; // [10:1:15]\n/* [Printer] */\nbed_x = ${p.bedX};\nbed_y = ${p.bedY};\nbed_z = ${p.bedZ};\nmargin = ${p.margin};\n/* [Segmentation] */\n// 0 = automatic. Explicit values avoid repeating the search on each render.\nsectors = ${m.layout.n}; // [0:2:32]\nrows = ${m.layout.rows}; // [0:1:12]\ngap = ${p.gap}; // [0.2:0.1:1]\nresolution = ${p.resolution}; // [2:1:10]\n/* [Print orientation and breakaway ribs] */\nsupports = ${p.supports}; // [0:Off,1:On]\nprint_angle = ${p.printAngle}; // -1 auto; 0 low profile; or 45-70 degrees\nrib_count = ${p.ribCount}; // [2:1:5]\ncontact_gap = ${p.contactGap}; // [0.1:0.05:0.4]\ncontact_width = ${p.contactWidth}; // [0.4:0.1:0.8]\nrib_pitch = ${p.ribPitch}; // [6:1:20]\n/* [Export] */\npart = "assembly"; // [assembly,panel,side-bridge,ring-bridge,hub-rear,hub-clamp]\nring = 1; // One-based radial ring index\n\n${kernel}`;}
export function manifest(m){return {generator:'PETAL 1.2',units:'mm',parameters:m.p,segmentation:{petals:m.layout.n,rings:m.layout.rows},focal_length:m.focal,dish_depth:m.depth,interface:{type:'custom',hub_outer_diameter:120,center_opening:30,rear_mount_bolt_circle:40,rear_mount_holes:4,rear_mount_clocking_degrees:45,clearance_window:4.6,hardware:'M4 bolts, nuts and washers'},assembly_bolts:m.bolts,parts:m.parts.map(p=>({file:`${p.id}${p.supportMeshes.length?'_supported':''}_qty-${p.qty}.stl`,quantity:p.qty,vertical_wall_range_mm:p.wallRange,grip_stack_range_mm:p.gripRange,petal_angle_degrees:p.angle,support_ribs:p.supportMeshes.length,support_volume_cm3:+(p.supportMeshes.reduce((s,r)=>s+volume(r),0)/1000).toFixed(3),bed_rotation_degrees:p.bedRotation,dimensions_mm:p.dim.map(x=>+x.toFixed(3)),solid_volume_cm3:+(volume(p.mesh)/1000).toFixed(3)})),notes:['Supports, when enabled, are separate closed shells included in each petal STL. Keep all shells in their original relative positions.','Supported petals are lifted 5.6 mm; rib feet start at Z=0. Unsupported parts start at Z=0.','Petal and bed angles are reported per part. Hubs and bridges retain low-profile orientation and may need slicer supports.','Angle selection is a geometric fit heuristic, not a simulation of strength or print reliability.','4.6 mm clearance windows are polar rectangles, not tapped threads.','Bolts, washers, reflector finish, feed, feed supports and mount adapter are not included.','Geometry checked digitally; physical fit and strength not validated.']};}
export function guide(m){return `# PETAL — assembly and print guide\n\n${m.p.diameter} mm diameter · f/D ${m.p.fd} · ${m.depth.toFixed(2)} mm depth · ${m.focal.toFixed(2)} mm focal length\n${m.layout.n} petals × ${m.layout.rows} concentric rings. All dimensions in millimetres.\n\n## Print list\n\n${m.parts.map(p=>`- ${p.id}${p.supportMeshes.length?'_supported':''}_qty-${p.qty}.stl — print ${p.qty}; ${p.dim.map(x=>x.toFixed(1)).join(' × ')} mm`).join('\n')}\n\n## Start with a fit check\n\nPrint one panel, one side bridge, and both hub rings before committing to a complete set. Digital volume and bed fit do not verify physical stiffness or tolerances. Larger dishes may require additional bracing.\n\nPetal orientations: ${m.parts.filter(p=>p.kind==='panel').map(p=>`ring ${p.row+1}: ${p.angle} degrees from bed, ${p.bedRotation} degrees bed rotation`).join('; ')}. Auto mode prefers 60 degrees when ribs or the two-facet rear are enabled, then tries 55, 50, 45 and 65 if needed to fit. Among fitting bed rotations (15-degree increments), it minimizes the bounding footprint. This is a geometric heuristic, not a proof of optimal strength or reliability. Concave faces point away from supports. CAD shell thickness is vertical; normal thickness decreases toward the rim.\n\n## Rear construction\n\n${m.p.rearStyle?'Two planar rear faces with a '+m.p.facetAngle+' degree change in slope. The front remains parabolic; thickness is the minimum vertical wall. Actual walls vary and corners may be substantially thicker.':'Curved rear with constant vertical wall thickness.'} Solid CAD volume assumes a fully solid body, not slicer infill. Matching backing bridges and rear hub are regenerated with the rear shape; reprint the complete kit after geometry changes. Faceted petals remain diagonal even without built-in ribs; matching backing parts have a flat base. No skeletonization is applied.\n\n## Optional breakaway ribs\n\nBuilt-in ribs: ${m.p.supports?'ON':'OFF'}. ${m.p.ribCount} ribs per petal, ${m.p.contactGap} mm nominal vertical contact gap, ${m.p.contactWidth} mm ridge width, ${m.p.ribPitch} mm tooth spacing. Each rib has a 1.2 mm web, an adaptive flared foot (up to 8 mm), and a narrow serrated upper ridge. Ribs follow the analytic rear envelope with a curvature allowance; actual clearance also includes mesh faceting. Footprint and height checks include enabled supports.\n\nWith ribs enabled, feet start at Z=0 and the petal is raised 5.6 mm. Import the combined petal STL as one object. Preserve the positions of its disconnected shells. Do NOT auto-arrange ribs or independently drop the petal to the bed. Check your slicer layer preview before disabling auto-generated supports for that petal. If the slicer ignores narrow ridges, increase ridge width or use a suitable extrusion width. A CAD contact gap does not automatically inherit slicer support-interface settings; tune it for material and layer height with one petal first. Hubs and bridges still may need slicer-generated support. The model count excludes disposable ribs.\n\nWithout built-in ribs, the petal rests at Z=0 at its selected angle. Use slicer supports as needed. Hub and bridge orientation remains low profile.\n\nSupport-setting background: https://help.prusa3d.com/article/support-material_1698\n\n## Hardware\n\n${m.bolts} M4 assembly bolts and nuts, with washers on both faces (plus four mount fasteners if used). ${m.p.rearStyle?m.parts.filter(p=>p.gripRange).map(p=>p.name+': '+p.gripRange.map(x=>x.toFixed(1)).join('–')+' mm grip').join('; '):'Bridge grip stack is approximately '+(m.p.thickness+3.4).toFixed(1)+' mm; hub clamp grip stack is approximately '+(m.p.thickness+9.6).toFixed(1)+' mm'}. Grip values exclude washers, nut and thread engagement. Choose actual bolt lengths for your hardware. Open clearance windows are 4.6 mm polar rectangles; there are no printed threads. Do not over-tighten plastic.\n\n## Assembly\n\n1. Identify inward versus outward edges. The inner panel has a bolt window at radius 52.5 mm; outer ring panels have inner windows 8 mm from their radial boundary.\n2. Place inner panel roots on the matching rear hub. Orient all panels with concave faces forward.\n3. Add the front clamp ring and ${m.layout.n} M4 root bolts. Leave loose until all inner panels are installed.\n4. Fit each side bridge behind its angular seam, with its two windows aligned to those in the neighboring panels.\n5. If there are outer rings, add them from the center outward. One radial bridge joins each pair of inner/outer panels. Add the side bridges for every ring.\n6. Tighten gently and check circularity and depth. A 0.2 mm assembly clearance separates each backing surface before tightening.\n\n## Center interface\n\nCustom pattern: 120 mm hub outer diameter; 30 mm central opening; four M4 clearance windows on a 40 mm bolt circle, starting at 45 degrees. The front clamp has an 86 mm center opening. Rear mount dimensions stay fixed across dish sizes. Root bolt count follows petal count; reprint both center rings when changing that count. Hub curvature follows focal length, so also regenerate it when geometry changes. Adapter and feed support are not included.\n\n## Surface and limitations\n\nPanels describe z = r²/(4f), with f = diameter × f/D. They are a polymer support shell, not a complete RF antenna. Panel seams, bolt windows, center opening, and protruding fasteners interrupt the surface. Reflective material, feed design, feed placement/support and other electronics are separate. No gain, sensitivity or frequency-specific performance is predicted.\n\n## OpenSCAD\n\nOpen petal.scad. Select a part and one-based ring number, F6 Render, then export STL. The default part is assembly for inspection, not an all-in-one printable part. Change diameter, focal ratio, thickness and printer parameters directly. Set sectors and/or rows to 0 to repeat automatic segmentation; explicit generated values make later renders faster. Render each unique part once and use quantities above. After edits, regenerate and recheck the entire set.\n\nGeometry engine: no dependencies. OpenSCAD syntax: https://openscad.org/cheatsheet/\n`;}
export function kit(m,kernel){return zip([...m.parts.map(p=>({name:`STL/${p.id}${p.supportMeshes.length?'_supported':''}_qty-${p.qty}.stl`,data:binarySTL(p.output)})),{name:'petal.scad',data:scadSource(m,kernel)},{name:'parameters.json',data:JSON.stringify(manifest(m),null,2)},{name:'ASSEMBLY.md',data:guide(m)}]);}
